sys_script_include.script:
var VendorUtils = Class.create();
VendorUtils.prototype = {
    initialize: function () {
        this._vendorTable = 'x_1610434_event_0_vendor';
    },

    getVendorDetailsById: function (_vendorId) {
        var _vendorGR = new GlideRecord(this._vendorTable);
        _vendorGR.addQuery('sys_id', _vendorId);
        _vendorGR.query();
        if (_vendorGR.next()) {
            return this._mapVendorFields(_vendorGR);
        }
        return null;
    },

    isVendorAvailable: function (_vendorId) {
        var _vendorGR = new GlideRecord(this._vendorTable);
        _vendorGR.addQuery('sys_id', _vendorId);
        _vendorGR.query();
        if (_vendorGR.next()) {
            return _vendorGR.availability.toString() == 'true';
        }
        return false;
    },

    getVendorsByEvent: function (_eventId) {
        var _vendorList = [];
        var _vendorGR = new GlideRecord(this._vendorTable);
        _vendorGR.addQuery('event_id', _eventId);
        _vendorGR.query();
        while (_vendorGR.next()) {
             _vendorList.push(this._mapVendorFields(_vendorGR));
        }
        return _vendorList;
    },

	_mapVendorFields: function (_vendorGR) {
        return {
            sysId: _vendorGR.getUniqueValue(),
            eventId: _vendorGR.getValue('event_id'),
            vendorName: _vendorGR.getValue('vendor_name'),
            contactPerson: _vendorGR.getValue('contact_person'),
            contactNumber: _vendorGR.getValue('contact_number'),
            servicesProvided: _vendorGR.getValue('services_provided'),
            availability: _vendorGR.availability.toString() == 'true',
            email: _vendorGR.getValue('email')
        };
    },

    type: 'VendorUtils'
};
